def get_advanced_settings() -> "AdvancedSettings":
    """
    Gibt die aktuellen erweiterten Einstellungen zurück.
    """
    try:
        return AdvancedSettings.load_from_file()
    except Exception as e:
        # Fallback für den unwahrscheinlichen Fall, dass selbst die Standardwerte fehlschlagen
        logger.critical(f"❌ Konnte AdvancedSettings nicht laden: {e}", exc_info=True)
        # Versuche, eine absolute Minimalinstanz zu erzeugen
        try:
            return AdvancedSettings()
        except Exception:
            raise RuntimeError("AdvancedSettings sind nicht verfügbar – Programm kann nicht fortgesetzt werden.") from e
    
# 19. HILFSFUNKTIONEN FÜR MAIN (Windows-Konsolenmanagement, System-Check, Argument-Parser, globale Exception-Handler)
_original_console_mode: Optional[int] = None
_original_codepage: Optional[int] = None


def _save_console_state() -> None:
    global _original_console_mode, _original_codepage
    if not IS_WINDOWS:
        return
    try:
        import ctypes

        kernel32 = ctypes.windll.kernel32
        handle = kernel32.GetStdHandle(-11)
        mode = ctypes.c_ulong()
        if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
            _original_console_mode = mode.value
        _original_codepage = kernel32.GetConsoleOutputCP()
    except Exception:
        pass


def _restore_console_state() -> None:
    """Stellt die ursprünglichen Konsolen-/Terminal-Einstellungen wieder her."""
    if IS_WINDOWS:
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32
            if _original_console_mode is not None:
                handle = kernel32.GetStdHandle(-11)
                kernel32.SetConsoleMode(handle, _original_console_mode)
            if _original_codepage is not None:
                kernel32.SetConsoleOutputCP(_original_codepage)
                kernel32.SetConsoleCP(_original_codepage)
        except Exception as e:
            logger.debug(f"Fehler beim Wiederherstellen der Windows-Konsole: {e}")
    else:
        # Linux / macOS: Terminal wieder in den normalen Modus versetzen
        try:
            subprocess.run(["stty", "sane"], check=False, timeout=1)
        except Exception as e:
            logger.debug(f"Fehler beim Wiederherstellen des Terminals: {e}")


_save_console_state()
atexit.register(_restore_console_state)


def _setup_windows_console() -> None:
    if not IS_WINDOWS:
        return
    try:
        import codecs

        sys.stdout = codecs.getwriter("utf-8")(sys.stdout.buffer)
        import ctypes

        kernel32 = ctypes.windll.kernel32
        kernel32.SetConsoleOutputCP(65001)
        kernel32.SetConsoleCP(65001)
        handle = kernel32.GetStdHandle(-11)
        mode = ctypes.c_ulong()
        if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
            ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
            new_mode = mode.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING
            kernel32.SetConsoleMode(handle, new_mode)
    except Exception:
        pass


def check_platform_compatibility() -> List[str]:
    issues: List[str] = []
    if sys.version_info < (3, 8):
        issues.append(
            f"Python 3.8+ required (you have {sys.version_info.major}.{sys.version_info.minor})"
        )
    if IS_WINDOWS:
        try:
            import platform

            win_ver = platform.version()
            major_ver = int(win_ver.split(".")[0]) if "." in win_ver else 0
            if major_ver < 10:
                issues.append("Windows 10+ recommended for best experience")
        except Exception:
            pass
    return issues


